 //  correctly. Too few is the opposite case: there is nothing sensible\n  //  to invent, so we refuse rather than send \"{{4}}\" to a customer.\n  // ---------------------------------------------------------------\n  let params = [...opts.params];\n  let buttonParam = opts.buttonParam ?? null;\n  let specLanguage: string | null = null;\n\n  if (opts.wabaId && !opts.language) {\n    const spec = await templateSpec(opts.wabaId, opts.token, opts.template);\n\n    if (spec) {\n      specLanguage = spec.language;\n\n      if (spec.bodyVars < params.length) {\n        console.log(\n          `[whatsapp] ${opts.template} has ${spec.bodyVars} body variables, we hold ` +\n            `${params.length} - sending the first ${spec.bodyVars}`,\n        );\n        params = params.slice(0, spec.bodyVars);\n      } else if (spec.bodyVars > params.length) {\n        return {\n          ok: false,\n          error:\n            `[params] ${opts.template} needs ${spec.bodyVars} body variables but only ` +\n            `${params.length} are available - not sent`,\n          permanent: true,\n        };\n      }\n\n      // A button variable is the same trap in miniature: a static URL\n      // button rejects a parameter, and a dynamic one requires it.\n      if (!spec.urlVar && buttonParam) {\n        console.log(`[whatsapp] ${opts.template} has a static button - dropping its parameter`);\n        buttonParam = null;\n      } else if (spec.urlVar && !buttonParam) {\n        return {\n          ok: false,\n          error: `[params] ${opts.template} has a dynamic button but no value for it - not sent`,\n          permanent: true,\n        };\n      }\n    }\n  }\n\n  const components: any[] = [];\n\n  if (params.length) {\n    components.push({\n      type: \"body\",\n      parameters: params.map((t) => ({ type: \"text\", text: t || \"-\" })),\n    });\n  }\n\n  if (buttonParam) {\n    components.push({\n      type: \"button\",\n      sub_type: \"url\",\n      index: \"0\",\n      parameters: [{ type: \"text\", text: buttonParam }],\n    });\n  }\n\n  // ---------------------------------------------------------------\n  //  Which language code to send.\n  //\n  //  A template is not stored under its name alone - it is stored under\n  //  (name, language). Ask for \"order_placed\" in \"en\" when Meta filed it\n  //  under \"en_US\" and you get error 132001 and nothing is delivered.\n  //  Meta's own console files English templates as en_US by default, so\n  //  hardcoding \"en\" was wrong.\n  //\n  //  So: look the template up in the account and use whatever language it\n  //  actually has. If that lookup cannot answer, try the two English codes\n  //  in turn rather than guessing once and failing.\n  // ---------------------------------------------------------------\n  const tries: string[] = [];\n\n  if (opts.language) {\n    tries.push(opts.language);\n  } else {\n    // The template lookup above already told us the language, so this\n    // costs nothing extra.\n    if (specLanguage) tries.push(specLanguage);\n    for (const fallback of [\"en_US\", \"en\"]) {\n      if (!tries.includes(fallback)) tries.push(fallback);\n    }\n  }\n\n  let last: SendResult = { ok: false, error: \"no language to try\", permanent: true };\n\n  for (const lang of tries) {\n    last = await attempt(lang);\n    // 132001 is the only error worth retrying with a different language.\n    if (last.ok || !last.error.startsWith(\"[132001]\")) return last;\n  }\n  return last;\n\n  async function attempt(lang: string): Promise<SendResult> {\n  const body = {\n    messaging_product: \"whatsapp\",\n    recipient_type: \"individual\",\n    to: opts.to,\n    type: \"template\",\n    template: {\n      name: opts.template,\n      language: { code: lang },\n      components,\n    },\n  };\n\n  try {\n    const res = await fetch(`${GRAPH}/${opts.phoneNumberId}/messages`, {\n      method: \"POST\",\n      headers: {\n        Authorization: `Bearer ${opts.token}`,\n        \"Content-Type\": \"application/json\",\n      },\n      body: JSON.stringify(body),\n    });\n\n    const json: any = await res.json().catch(() => ({}));\n\n    if (res.ok && json?.messages?.[0]?.id) {\n      return { ok: true, id: json.messages[0].id };\n    }\n\n    const err = json?.error ?? {};\n    const code = Number(err.code ?? 0);\n    const msg =\n      [err.message, err.error_data?.details].filter(Boolean).join(\" - \") ||\n      `HTTP ${res.status}`;\n\n    // ---------------------------------------------------------------\n    //  Which errors are worth retrying, and which are not.\n    //\n    //  Wrong number, template does not exist, customer has blocked us -\n    //  resending will not fix any of these. We treat them as permanent\n    //  and drop them from the queue.\n    //\n    //  Rate limits or Meta's own server being down - these clear up after\n    //  a while, so they should be retried.\n    // ---------------------------------------------------------------\n    const permanent = [100, 131009, 131026, 131047, 132000, 132001, 132005, 132007, 132012, 132015].includes(code);\n\n    return { ok: false, error: `[${code}] ${msg}`, permanent };\n  } catch (e: any) {\n    // the network dropped - retry later\n    return { ok: false, error: String(e?.message ?? e), permanent: false };\n  }\n  }\n}\n\n/* ------------------------------------------------------------------ */\n/*  Template name -> language                                          */\n/* ------------------------------------------------------------------ */\n\ntype Cached = { at: number; list: any[] };\nconst tplCache = new Map<string, Cached>();\nconst TTL = 5 * 60 * 1000;\n\n/** The whole template list for an account, cached for five minutes. */\nasync function allTemplates(wabaId: string, token: string, force = false): Promise<any[]> {\n  const hit = tplCache.get(wabaId);\n  if (!force && hit && Date.now() - hit.at < TTL) return hit.list;\n\n  const r = await listTemplates(wabaId, token);\n  if (!r.ok) return hit?.list ?? [];\n\n  tplCache.set(wabaId, { at: Date.now(), list: r.templates });\n  return r.templates;\n}\n\n/**\n * One template by name. An approved entry wins over a pending one, because\n * only an approved template can actually be sent.\n */\nexport async function findTemplate(wabaId: string, token: string, name: string) {\n  let matches = (await allTemplates(wabaId, token)).filter((t: any) => t?.name === name);\n  if (matches.length === 0) {\n    // Just created, and our cache predates it - look once more, fresh.\n    matches = (await allTemplates(wabaId, token, true)).filter((t: any) => t?.name === name);\n  }\n  if (matches.length === 0) return null;\n  return matches.find((t: any) => t.status === \"APPROVED\") ?? matches[0];\n}\n\n/**\n * What a template actually needs before it can be sent: how many body\n * variables, and whether its URL button carries one.\n *\n * Getting this wrong is its own error (132000, wrong number of parameters),\n * so it is worth reading rather than assuming. hello_world, for instance,\n * takes none at all.\n */\nexport async function templateSpec(wabaId: string, token: string, name: string) {\n  const t = await findTemplate(wabaId, token, name);\n  if (!t) return null;\n\n  let bodyVars = 0;\n  let urlVar = false;\n\n  for (const c of t.components ?? []) {\n    const type = String(c?.type ?? \"\").toUpperCase();\n\n    if (type === \"BODY\") {\n      for (const m of String(c?.text ?? \"\").matchAll(/\\{\\{\\s*(\\d+)\\s*\\}\\}/g)) {\n        bodyVars = Math.max(bodyVars, Number(m[1]));\n      }\n    }\n    if (type === \"BUTTONS\") {\n      for (const b of c?.buttons ?? []) {\n        if (String(b?.type ?? \"\").toUpperCase() === \"URL\" && /\\{\\{\\s*\\d+\\s*\\}\\}/.test(String(b?.url ?? \"\"))) {\n          urlVar = true;\n        }\n      }\n    }\n  }\n\n  return {\n    name: t.name as string,\n    language: t.language as string,\n    status: t.status as string,\n    bodyVars,\n    urlVar,\n  };\n}\n\n/**\n * Every template name in the account with the language it was filed under.\n * Cached for five minutes - a merchant does not add templates every second,\n * and asking Meta before each message would be slow and rate-limited.\n */\n/** The language this one template is filed under, or null if unknown. */\nexport async function resolveLanguage(\n  wabaId: string,\n  token: string,\n  name: string,\n): Promise<string | null> {\n  const t = await findTemplate(wabaId, token, name);\n  return t?.language ?? null;\n}\n\n/** Tells you whether the number and token are valid without sending a message. */\nexport async function checkCredentials(phoneNumberId: string, token: string) {\n  try {\n    const res = await fetch(\n      `${GRAPH}/${phoneNumberId}?fields=display_phone_number,verified_name,quality_rating`,\n      { headers: { Authorization: `Bearer ${token}` } },\n    );\n    const json: any = await res.json().catch(() => ({}));\n    if (res.ok && json?.id) {\n      return {\n        ok: true as const,\n        number: json.display_phone_number as string,\n        name: json.verified_name as string,\n        quality: json.quality_rating as string,\n      };\n    }\n    return { ok: false as const, error: json?.error?.message ?? `HTTP ${res.status}` };\n  } catch (e: any) {\n    return { ok: false as const, error: String(e?.message ?? e) };\n  }\n}\n\n/** Which templates have been approved - for display on the admin page. */\nexport async function listTemplates(wabaId: string, token: string) {\n  try {\n    const res = await fetch(\n      `${GRAPH}/${wabaId}/message_templates?fields=name,status,category,language,components&limit=200`,\n      { headers: { Authorization: `Bearer ${token}` } },\n    );\n    const json: any = await res.json().catch(() => ({}));\n    if (res.ok && Array.isArray(json?.data)) {\n      return { ok: true as const, templates: json.data as any[] };\n    }\n    return { ok: false as const, error: json?.error?.message ?? `HTTP ${res.status}` };\n  } catch (e: any) {\n    return { ok: false as const, error: String(e?.message ?? e) };\n  }\n}\n"}, {"path": "app/routes/api.cron.tsx", "fromShas": ["33b010f0425ceb6839d75c3fe71d7ab1a6ecdd51423d51d5a5409fc9adc0b187"], "toSha": "64769b7b4fc650ff701b4a2c6ad9fada80b9c879fa30fb58ae32e3ff3eca0ba1", "content": "import type { LoaderFunctionArgs, ActionFunctionArgs } from \"react-router\";\nimport db from \"../db.server\";\nimport {\n  registerNumbers, getTrackInfo, chunk,\n  ALREADY_REGISTERED, NO_CARRIER, QUOTA_OVER,\n} from \"../lib/track.server\";\nimport { applyToShipment, FINAL } from \"../lib/tracksync.server\";\nimport { sweepAbandoned } from \"../lib/abandoned.server\";\nimport { sweepCancelRequests } from \"../lib/inbound.server\";\n\n/**\n * The clock job.\n *\n * Call this once every 15 minutes (Render/Railway cron, or\n * cron-job.org works just as well):\n *\n *     https://<app-url>/api/cron?key=<CRON_SECRET>\n *\n * It does three things:\n *   1. Register new tracking numbers with 17TRACK\n *   2. Ask for the status of parcels still in transit (in case a push is missed)\n *   3. Abandoned cart reminders\n *   4. Cancellations the customer asked for, once the grace period is over\n *\n * The push (webhook) arrives instantly, this is its backup. We need both -\n * push is fast but drops occasionally, polling is slow but reliable.\n */\n\nconst THREE_HOURS = 3 * 60 * 60 * 1000;\n\nasync function run() {\n  const out = {\n    registered: 0,\n    regFailed: 0,\n    polled: 0,\n    changed: 0,\n    abandoned1: 0,\n    abandoned2: 0,\n    cancelled: 0,\n    cancelTooLate: 0,\n    notes: [] as string[],\n  };\n\n  const shops = await db.shop.findMany({ where: { trackApiKey: { not: null } } });\n\n  for (const shop of shops) {\n    const key = shop.trackApiKey!;\n\n    /* ---------- 1. register ---------- */\n    const fresh = await db.shipment.findMany({\n      where: {\n        registered: false,\n        regTries: { lt: 5 },\n        trackingNo: { not: null },\n        order: { shopId: shop.id },\n      },\n      include: { order: true },\n      take: 80,\n    });\n\n    for (const batch of chunk(fresh, 40)) {\n      const res = await registerNumbers(\n        key,\n        batch.map((s) => ({\n          number: s.trackingNo!,\n          order_no: s.order.orderNumber,\n          tag: s.id,\n          param: s.id,\n        })),\n      );\n\n      // The whole call failed - quota exhausted or a bad key. We bump the\n      // try count so it does not hammer this a thousand times every 15 minutes.\n      if (!res.ok) {\n        out.notes.push(`register: ${res.error}`);\n        await db.shipment.updateMany({\n          where: { id: { in: batch.map((s) => s.id) } },\n          data: { regTries: { increment: 1 } },\n        });\n        if (res.code === QUOTA_OVER) out.notes.push(\"17TRACK quota exhausted\");\n        break;\n      }\n\n      const okNums = new Set(res.accepted.map((a: any) => String(a.number)));\n      const permanentFail = new Set<string>();\n\n      for (const r of res.rejected) {\n        const code = r?.error?.code;\n        const num = String(r?.number ?? \"\");\n        // \"already registered\" is not an error - it means tracking is running.\n        if (code === ALREADY_REGISTERED) okNums.add(num);\n        else if (code === NO_CARRIER) permanentFail.add(num);\n        else out.notes.push(`${num}: ${r?.error?.message ?? code}`);\n      }\n\n      for (const s of batch) {\n        const num = s.trackingNo!;\n        if (okNums.has(num)) {\n          await db.shipment.update({\n            where: { id: s.id },\n            data: { registered: true, regTries: { increment: 1 } },\n          });\n          out.registered++;\n        } else {\n          await db.shipment.update({\n            where: { id: s.id },\n            data: { regTries: { increment: permanentFail.has(num) ? 5 : 1 } },\n          });\n          out.regFailed++;\n        }\n      }\n    }\n\n    /* ---------- 2. poll status ---------- */\n    const live = await db.shipment.findMany({\n      where: {\n        registered: true,\n        trackingNo: { not: null },\n        order: { shopId: shop.id },\n        status: { notIn: Array.from(FINAL) },\n        OR: [\n          { lastEventAt: null },\n          { lastEventAt: { lte: new Date(Date.now() - THREE_HOURS) } },\n        ],\n      },\n      take: 40,\n    });\n\n    for (const batch of chunk(live, 40)) {\n      const res = await getTrackInfo(key, batch.map((s) => s.trackingNo!));\n      if (!res.ok) {\n        out.notes.push(`gettrackinfo: ${res.error}`);\n        break;\n      }\n      for (const node of res.accepted) {\n        const num = String(node?.number ?? \"\");\n        const s = batch.find((x) => x.trackingNo === num);\n        if (!s) continue;\n        const r = await applyToShipment(s.id, node);\n        out.polled++;\n        if (r?.changed) out.changed++;\n      }\n    }\n  }\n\n  /* ---------- 3. abandoned carts ---------- */\n  const ab = await sweepAbandoned();\n  out.abandoned1 = ab.sent1;\n  out.abandoned2 = ab.sent2;\n\n  /* ---------- 4. cancellations the customer asked for ----------\n     Pressing Cancel on WhatsApp does not cancel anything at once. A\n     cancelled Shopify order cannot be brought back, and a button is easy\n     to press by accident. So the request waits out a grace period here,\n     and a Confirm arriving in the meantime wipes it. */\n  const cx = await sweepCancelRequests();\n  out.cancelled = cx.cancelled;\n  out.cancelTooLate = cx.tooLate;\n\n  console.log(\"[cron]\", JSON.stringify(out));\n  return out;\n}\n\nfunction guard(request: Request): Response | null {\n  const url = new URL(request.url);\n  const given = url.searchParams.get(\"key\") ?? request.headers.get(\"x-cron-key\");\n  const want = process.env.CRON_SECRET;\n  if (!want) return new Response(\"CRON_SECRET is not set in .env\", { status: 500 });\n  if (given !== want) return new Response(\"nope\", { status: 401 });\n  return null;\n}\n\nexport const loader = async ({ request }: LoaderFunctionArgs) => {\n  const bad = guard(request);\n  if (bad) return bad;\n  return Response.json(await run());\n};\n\nexport const action = async ({ request }: ActionFunctionArgs) => {\n  const bad = guard(request);\n  if (bad) return bad;\n  return Response.json(await run());\n};\n"}, {"path": "app/routes/app._index.tsx", "fromShas": ["26b6f9a6ad0e505ab92a66b38c8ad452bcdeb92045a8675f0858907165b5bfc3"], "toSha": "33490f64e0d3c4c7e4f3be5ff0a71985b932f4bfe53d913a06187c1d6cbc8b3e", "content": "import { useState } from \"react\";\nimport type { LoaderFunctionArgs, ActionFunctionArgs } from \"react-router\";\nimport { useLoaderData, useFetcher, useActionData, Form } from \"react-router\";\n\nimport { authenticate } from \"../shopify.server\";\nimport db from \"../db.server\";\nimport { ensureShop, toE164 } from \"../lib/webhook.server\";\nimport { checkCredentials, listTemplates, sendTemplate, templateSpec } from \"../lib/whatsapp.server\";\nimport { EVENTS, blankVars } from \"../lib/templates.server\";\n\n/**\n * Admin page.\n *\n * Polaris is deliberately not used here. The new Shopify template does\n * not ship @shopify/polaris at all, and pulling in two heavy packages\n * just for this one page and wiring up their CSS/AppProvider - that\n * raises the risk for the whole app. Plain HTML works in every template.\n */\n\nexport const loader = async ({ request }: LoaderFunctionArgs) => {\n  const { session } = await authenticate.admin(request);\n  const shop = await ensureShop(session.shop);\n\n  const [messages, orders, queued, parcels, tracked] = await Promise.all([\n    db.messageLog.findMany({\n      where: { shopId: shop.id },\n      orderBy: { createdAt: \"desc\" },\n      take: 25,\n    }),\n    db.orderRecord.count({ where: { shopId: shop.id } }),\n    db.messageLog.count({ where: { shopId: shop.id, status: \"queued\" } }),\n    db.shipment.findMany({\n      where: { order: { shopId: shop.id } },\n      orderBy: { updatedAt: \"desc\" },\n      take: 10,\n      include: { order: true },\n    }),\n    db.shipment.count({ where: { order: { shopId: shop.id }, registered: true } }),\n  ]);\n\n  // The merchant's inbox. A Cloud API number cannot be opened in the normal\n  // WhatsApp Business app, so this table is the only place replies exist.\n  const replies = await db.inboundMessage.findMany({\n    where: { shopId: shop.id },\n    orderBy: { createdAt: \"desc\" },\n    take: 20,\n    include: { order: { select: { orderNumber: true } } },\n  });\n\n  const awaitingCancel = await db.orderRecord.findMany({\n    where: { shopId: shop.id, cancelRequestedAt: { not: null }, cancelledAt: null },\n    orderBy: { cancelRequestedAt: \"asc\" },\n    take: 20,\n  });\n\n  let live: any = null;\n  let templates: any[] = [];\n  if (shop.waToken && shop.waPhoneNumberId) {\n    live = await checkCredentials(shop.waPhoneNumberId, shop.waToken);\n    if (shop.waWabaId) {\n      const t = await listTemplates(shop.waWabaId, shop.waToken);\n      if (t.ok) templates = t.templates;\n    }\n  }\n\n  // Which of our templates are not approved yet.\n  //\n  // This has to be worked out HERE, not in the component. EVENTS lives in\n  // templates.server.ts, and React Router only strips server-only imports\n  // that nothing outside loader/action touches. Reading it from the\n  // component pulled the whole server module into the browser bundle, the\n  // page stopped hydrating, and every button on it went dead.\n  const approved = new Set(\n    templates.filter((t: any) => t.status === \"APPROVED\").map((t: any) => t.name),\n  );\n  const missing = Array.from(new Set(Object.values(EVENTS).map((e) => e.template)))\n    .filter((n) => !approved.has(n));\n\n  // How many {{n}} the template really has, next to how many the app holds\n  // for it. When those two numbers disagree the message is refused with\n  // 132000 and the customer gets nothing - so it is worth seeing here\n  // rather than finding out from a failed send.\n  const blank = blankVars();\n  const ours = new Map<string, number>();\n  for (const def of Object.values(EVENTS)) {\n    ours.set(def.template, def.params(blank).length);\n  }\n\n  function bodyVarsOf(t: any): number {\n    let n = 0;\n    for (const comp of t?.components ?? []) {\n      if (String(comp?.type ?? \"\").toUpperCase() !== \"BODY\") continue;\n      for (const m of String(comp?.text ?? \"\").matchAll(/\\{\\{\\s*(\\d+)\\s*\\}\\}/g)) {\n        n = Math.max(n, Number(m[1]));\n      }\n    }\n    return n;\n  }\n\n  const templateList = templates\n    .map((t: any) => ({\n      name: t.name,\n      status: t.status,\n      language: t.language,\n      needs: bodyVarsOf(t),\n      sends: ours.has(t.name) ? ours.get(t.name)! : null,\n    }))\n    .sort((a: any, b: any) => String(a.name).localeCompare(String(b.name)));\n\n  return {\n    shop, messages, orders, queued, live, missing, templateList, parcels, tracked,\n    replies, awaitingCancel,\n    domain: session.shop,\n    appUrl: process.env.SHOPIFY_APP_URL ?? \"\",\n    cronSet: Boolean(process.env.CRON_SECRET),\n  };\n};\n\nexport const action = async ({ request }: ActionFunctionArgs) => {\n  const { session } = await authenticate.admin(request);\n  const shop = await ensureShop(session.shop);\n  const fd = await request.formData();\n  const intent = String(fd.get(\"intent\") || \"\");\n\n  console.log(`[admin] action reached: intent=\"${intent}\" shop=${session.shop}`);\n\n  if (intent === \"save\") {\n    const str = (k: string) => {\n      const v = String(fd.get(k) ?? \"\").trim();\n      return v === \"\" ? null : v;\n    };\n    const on = (k: string) => fd.get(k) === \"on\";\n\n    await db.shop.update({\n      where: { id: shop.id },\n      data: {\n        waPhoneNumberId: str(\"waPhoneNumberId\"),\n        waWabaId: str(\"waWabaId\"),\n        // If the token is left empty we keep the old one - otherwise it would\n        // have to be pasted on every save, and one slip would stop everything.\n        waToken: str(\"waToken\") ?? shop.waToken,\n        trackApiKey: str(\"trackApiKey\") ?? shop.trackApiKey,\n        abandonCode: str(\"abandonCode\"),\n        waEnabled: on(\"waEnabled\"),\n        onOrderCreate: on(\"onOrderCreate\"),\n        codConfirm: on(\"codConfirm\"),\n        onOrderPaid: on(\"onOrderPaid\"),\n        onFulfilled: on(\"onFulfilled\"),\n        onInTransit: on(\"onInTransit\"),\n        onOutForDelivery: on(\"onOutForDelivery\"),\n        onDelivered: on(\"onDelivered\"),\n        onCancelled: on(\"onCancelled\"),\n        onAbandoned: on(\"onAbandoned\"),\n        autoCancel: on(\"autoCancel\"),\n        cancelGraceMin: Math.min(\n          720,\n          Math.max(5, Number(fd.get(\"cancelGraceMin\")) || 30),\n        ),\n      },\n    });\n    const after = await db.shop.findUnique({ where: { id: shop.id } });\n    console.log(\n      `[admin] saved -> phoneNumberId=${after?.waPhoneNumberId ?? \"null\"}` +\n        ` wabaId=${after?.waWabaId ?? \"null\"}` +\n        ` token=${after?.waToken ? \"set\" : \"null\"}` +\n        ` trackKey=${after?.trackApiKey ? \"set\" : \"null\"}` +\n        ` enabled=${after?.waEnabled}`,\n    );\n\n    return { ok: true, msg: \"Settings saved\" };\n  }\n\n  if (intent === \"test\") {\n    const to = toE164(String(fd.get(\"testTo\") || \"\"));\n    const fresh = await db.shop.findUnique({ where: { id: shop.id } });\n\n    if (!to) {\n      console.log(\"[admin] test: that number does not look right\");\n      return { ok: false, msg: \"That number does not look right\" };\n    }\n    if (!fresh?.waToken || !fresh?.waPhoneNumberId) {\n      console.log(\"[admin] test: phone number ID or token is missing\");\n      return { ok: false, msg: \"Enter the phone number ID and token first, then save\" };\n    }\n\n    const name = String(fd.get(\"testTemplate\") || \"hello_world\").trim();\n\n    // Read what the template actually needs instead of assuming five body\n    // variables. hello_world takes none; sending five would fail with 132000\n    // and look like a different problem entirely.\n    const spec = fresh.waWabaId\n      ? await templateSpec(fresh.waWabaId, fresh.waToken, name)\n      : null;\n\n    if (fresh.waWabaId && !spec) {\n      const msg = `No template named \"${name}\" in this WhatsApp account`;\n      console.log(`[admin] test -> ${msg}`);\n      return { ok: false, msg };\n    }\n    if (spec && spec.status !== \"APPROVED\") {\n      const msg = `Template \"${name}\" is ${spec.status}, not APPROVED - Meta will not send it yet`;\n      console.log(`[admin] test -> ${msg}`);\n      return { ok: false, msg };\n    }\n\n    const SAMPLES = [\n      \"Sadik\", \"Z1005\", \"Portable Blender\", \"INR 899\", \"3-7 September\",\n      \"Delhivery\", \"1234567890\", \"Patna\", \"Bettiah, Bihar 845438\", \"WELCOME10\",\n    ];\n    const params = SAMPLES.slice(0, spec?.bodyVars ?? 0);\n\n    const res = await sendTemplate({\n      phoneNumberId: fresh.waPhoneNumberId,\n      token: fresh.waToken,\n      wabaId: fresh.waWabaId,\n      to,\n      template: name,\n      language: spec?.language,\n      params,\n      buttonParam: spec?.urlVar ? \"test123\" : null,\n    });\n\n    // Printed to the terminal as well as returned to the page. Whatever Meta\n    // says here is the only thing that explains a message that never arrives,\n    // and hunting for a banner in an embedded iframe is no way to read it.\n    console.log(\n      res.ok\n        ? `[admin] test -> Meta accepted it, id ${res.id}`\n        : `[admin] test -> REJECTED by Meta: ${res.error}`,\n    );\n\n    return res.ok\n      ? { ok: true, msg: `Sent. Check your WhatsApp (id ${res.id.slice(-8)})` }\n      : { ok: false, msg: res.error };\n  }\n\n  return { ok: false, msg: \"Could not understand that request\" };\n};\n\n/* ------------------------------------------------------------------ */\n/*  small UI pieces                                                    */\n/* ------------------------------------------------------------------ */\n\nconst S = {\n  page: { maxWidth: 860, margin: \"0 auto\", padding: \"24px 16px 80px\",\n    font: \"14px/1.5 -apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif\",\n    color: \"#1a1a1a\" } as React.CSSProperties,\n  card: { background: \"#fff\", border: \"1px solid #e3e3e3\", borderRadius: 12,\n    padding: 20, marginBottom: 16, boxShadow: \"0 1px 2px rgba(0,0,0,.04)\" } as React.CSSProperties,\n  h2: { margin: \"0 0 14px\", fontSize: 16, fontWeight: 650 } as React.CSSProperties,\n  label: { display: \"block\", fontSize: 13, fontWeight: 550, marginBottom: 5 } as React.CSSProperties,\n  input: { width: \"100%\", padding: \"9px 11px\", border: \"1px solid #8a8a8a\",\n    borderRadius: 8, fontSize: 14, boxSizing: \"border-box\" } as React.CSSProperties,\n  help: { fontSize: 12, color: \"#616161\", margin: \"5px 0 0\" } as React.CSSProperties,\n  field: { marginBottom: 16 } as React.CSSProperties,\n  btn: { background: \"#303030\", color: \"#fff\", border: 0, borderRadius: 8,\n    padding: \"9px 18px\", fontSize: 14, fontWeight: 550, cursor: \"pointer\" } as React.CSSProperties,\n  row: { display: \"flex\", gap: 8, alignItems: \"flex-start\", marginBottom: 12 } as React.CSSProperties,\n  stat: { flex: \"1 1 170px\", background: \"#fff\", border: \"1px solid #e3e3e3\",\n    borderRadius: 12, padding: \"16px 18px\" } as React.CSSProperties,\n  muted: { color: \"#616161\", fontSize: 12, margin: 0 } as React.CSSProperties,\n  big: { fontSize: 22, fontWeight: 650, margin: \"4px 0 0\" } as React.CSSProperties,\n  th: { textAlign: \"left\", fontSize: 12, color: \"#616161\", fontWeight: 550,\n    padding: \"8px 10px\", borderBottom: \"1px solid #e3e3e3\" } as React.CSSProperties,\n  td: { padding: \"9px 10px\", borderBottom: \"1px solid #f1f1f1\", verticalAlign: \"top\" } as React.CSSProperties,\n  code: { background: \"#f1f1f1\", borderRadius: 5, padding: \"1px 6px\",\n    fontFamily: \"ui-monospace,SFMono-Regular,Menlo,monospace\", fontSize: 12 } as React.CSSProperties,\n};\n\nfunction Banner({ tone, title, children }:\n  { tone: \"success\" | \"critical\" | \"warning\"; title?: string; children?: any }) {\n  const c = tone === \"success\" ? { bg: \"#e6f6ec\", bd: \"#0f7a3d\" }\n    : tone === \"critical\" ? { bg: \"#fdeceb\", bd: \"#c4262e\" }\n    : { bg: \"#fff4e4\", bd: \"#b98900\" };\n  return (\n    <div style={{ background: c.bg, borderLeft: `4px solid ${c.bd}`, borderRadius: 10,\n      padding: \"12px 16px\", marginBottom: 16 }}>\n      {title && <p style={{ margin: \"0 0 4px\", fontWeight: 650 }}>{title}</p>}\n      <div style={{ fontSize: 13 }}>{children}</div>\n    </div>\n  );\n}\n\nfunction Pill({ status }: { status: string }) {\n  const c = status === \"sent\" ? { bg: \"#e6f6ec\", fg: \"#0b5c2e\" }\n    : status === \"failed\" ? { bg: \"#fdeceb\", fg: \"#8e1c22\" }\n    : { bg: \"#fff4e4\", fg: \"#7a5a00\" };\n  const t = status === \"sent\" ? \"Sent\" : status === \"failed\" ? \"Failed\" : \"Queued\";\n  return <span style={{ background: c.bg, color: c.fg, borderRadius: 20,\n    padding: \"2px 10px\", fontSize: 12, fontWeight: 600 }}>{t}</span>;\n}\n\nfunction Text({ label, name, defaultValue, placeholder, help, type }: any) {\n  return (\n    <div style={S.field}>\n      <label style={S.label} htmlFor={name}>{label}</label>\n      <input style={S.input} id={name} name={name} type={type ?? \"text\"}\n        defaultValue={defaultValue} placeholder={placeholder} autoComplete=\"off\" />\n      {help && <p style={S.help}>{help}</p>}\n    </div>\n  );\n}\n\nfunction Check({ label, name, defaultChecked, help }: any) {\n  return (\n    <div style={{ marginBottom: 12 }}>\n      <label style={{ display: \"flex\", gap: 8, alignItems: \"flex-start\", cursor: \"pointer\" }}>\n        <input type=\"checkbox\" name={name} defaultChecked={defaultChecked}\n          style={{ marginTop: 3, width: 16, height: 16 }} />\n        <span>\n          <span style={{ fontWeight: 550 }}>{label}</span>\n          {help && <span style={{ display: \"block\", ...S.help }}>{help}</span>}\n        </span>\n      </label>\n    </div>\n  );\n}\n\n/* ------------------------------------------------------------------ */\n\nexport default function Index() {\n  const { shop, messages, orders, queued, live, missing, templateList, parcels,\n    tracked, domain, appUrl, cronSet, replies, awaitingCancel } =\n    useLoaderData<typeof loader>();\n  const fetcher = useFetcher<typeof action>();\n  // The settings form is a plain <Form>, so its result comes back through\n  // useActionData, not through the fetcher. Without this the Save button\n  // gave no feedback at all - it looked like nothing had happened.\n  const actionData = useActionData<typeof action>();\n  const result = fetcher.data ?? actionData;\n  const [testTo, setTestTo] = useState(\"\");\n\n  return (\n    <div style={S.page}>\n      <h1 style={{ fontSize: 20, fontWeight: 700, margin: \"0 0 18px\" }}>ZakTracking</h1>\n\n      {result && (\n        <Banner tone={result.ok ? \"success\" : \"critical\"}>{result.msg}</Banner>\n      )}\n\n      <div style={{ display: \"flex\", gap: 12, flexWrap: \"wrap\", marginBottom: 16 }}>\n        <div style={S.stat}>\n          <p style={S.muted}>Orders</p>\n          <p style={S.big}>{orders}</p>\n        </div>\n        <div style={S.stat}>\n          <p style={S.muted}>In queue</p>\n          <p style={S.big}>{queued}</p>\n        </div>\n        <div style={S.stat}>\n          <p style={S.muted}>Parcels in tracking</p>\n          <p style={S.big}>{tracked}</p>\n        </div>\n        <div style={S.stat}>\n          <p style={S.muted}>WhatsApp</p>\n          <p style={S.big}>{live?.ok ? live.number : shop.waEnabled ? \"Error\" : \"Off\"}</p>\n          {live?.ok && (\n            <p style={S.muted}>{live.name} · quality {live.quality ?? \"-\"}</p>\n          )}\n        </div>\n      </div>\n\n      {live && !live.ok && (\n        <Banner tone=\"critical\" title=\"Cannot reach WhatsApp\">\n          <p style={{ margin: \"0 0 4px\" }}>{live.error}</p>\n          <p style={{ margin: 0 }}>\n            The token may have expired. Create a new one from a system user in\n            Business settings and paste it here.\n          </p>\n        </Banner>\n      )}\n\n      {live?.ok && missing.length > 0 && (\n        <Banner tone=\"warning\" title={`${missing.length} templates are not approved yet`}>\n          <p style={{ margin: \"0 0 4px\" }}>{missing.join(\", \")}</p>\n          <p style={{ margin: 0 }}>\n            Templates that are not approved cannot be sent. Check WhatsApp Manager.\n          </p>\n        </Banner>\n      )}\n\n      <div style={S.card}>\n        <Form method=\"post\">\n          <input type=\"hidden\" name=\"intent\" value=\"save\" />\n          <h2 style={S.h2}>WhatsApp connection</h2>\n\n          <Text label=\"Phone number ID\" name=\"waPhoneNumberId\"\n            defaultValue={shop.waPhoneNumberId ?? \"\"}\n            help=\"Found in the Meta app under WhatsApp → API Setup\" />\n\n          <Text label=\"WhatsApp Business Account ID\" name=\"waWabaId\"\n            defaultValue={shop.waWabaId ?? \"\"}\n            help=\"This keeps the template list and their status visible here\" />\n\n          <Text label=\"Permanent access token\" name=\"waToken\" type=\"password\"\n            placeholder={shop.waToken ? \"•••••••• (already saved)\" : \"EAAx...\"}\n            help=\"Leave it empty to keep the current one. Do not share it with anyone.\" />\n\n          <Text label=\"17TRACK API key\" name=\"trackApiKey\" type=\"password\"\n            placeholder={shop.trackApiKey ? \"•••••••• (saved)\" : \"not set yet\"}\n            help=\"Out for delivery and Delivered come from this. 100 trackings free a month.\" />\n\n          <Text label=\"Abandoned cart discount code\" name=\"abandonCode\"\n            defaultValue={shop.abandonCode ?? \"\"}\n            placeholder=\"e.g. WELCOME10\"\n            help=\"The second reminder (24 hours) goes out with this code. If it is empty the second reminder is not sent at all — better than sending a fake code.\" />\n\n          <Check label=\"Turn on message sending\" name=\"waEnabled\" defaultChecked={shop.waEnabled}\n            help=\"If this is off, everything stays in the queue and nothing is sent\" />\n\n          <hr style={{ border: 0, borderTop: \"1px solid #e3e3e3\", margin: \"18px 0\" }} />\n          <h2 style={S.h2}>Which messages to send</h2>\n\n          <Check label=\"Order received\" name=\"onOrderCreate\" defaultChecked={shop.onOrderCreate} />\n          <Check label=\"Ask for COD confirmation\" name=\"codConfirm\" defaultChecked={shop.codConfirm}\n            help=\"This prevents the most RTO. A callback URL is needed to receive the button reply — that is still pending.\" />\n          <Check label=\"Payment received (prepaid only)\" name=\"onOrderPaid\" defaultChecked={shop.onOrderPaid} />\n          <Check label=\"Shipped + tracking\" name=\"onFulfilled\" defaultChecked={shop.onFulfilled} />\n          <Check label=\"In transit\" name=\"onInTransit\" defaultChecked={shop.onInTransit}\n            help=\"Goes out once per order, the first time the courier scans it in transit - not on every hub. Worth turning on only for long routes, where it reassures. On a three-day delivery it lands right after the shipped message and reads as a repeat.\" />\n          <Check label=\"Out for delivery\" name=\"onOutForDelivery\" defaultChecked={shop.onOutForDelivery}\n            help=\"This will not arrive without 17TRACK — Shopify does not send this status\" />\n          <Check label=\"Delivered\" name=\"onDelivered\" defaultChecked={shop.onDelivered}\n            help=\"This also comes from 17TRACK\" />\n          <Check label=\"Cancelled\" name=\"onCancelled\" defaultChecked={shop.onCancelled} />\n          <Check label=\"Abandoned cart\" name=\"onAbandoned\" defaultChecked={shop.onAbandoned}\n            help=\"Marketing category — ₹0.92 per message, seven times Utility\" />\n\n          <hr style={{ border: 0, borderTop: \"1px solid #e3e3e3\", margin: \"18px 0\" }} />\n          <h2 style={S.h2}>When a customer cancels on WhatsApp</h2>\n\n          <Check label=\"Cancel the order automatically\" name=\"autoCancel\"\n            defaultChecked={shop.autoCancel}\n            help=\"Nothing is cancelled the moment the button is pressed. The request waits for the time below, and if the customer presses Confirm in the meantime it is dropped and the order stands — a cancelled Shopify order can never be brought back.\" />\n\n          <Text label=\"Wait before cancelling (minutes)\" name=\"cancelGraceMin\"\n            type=\"number\"\n            defaultValue={String(shop.cancelGraceMin)}\n            help=\"Between 5 and 720. Prepaid orders and anything already handed to the courier are never cancelled here — those are tagged for you to decide.\" />\n\n          <button type=\"submit\" style={S.btn}>Save</button>\n\n          <p style={{ ...S.help, marginTop: 12 }}>\n            Currently stored: phone number ID{\" \"}\n            <b>{shop.waPhoneNumberId ?? \"not set\"}</b>, WABA ID{\" \"}\n            <b>{shop.waWabaId ?? \"not set\"}</b>, token{\" \"}\n            <b>{shop.waToken ? \"set\" : \"not set\"}</b>, 17TRACK key{\" \"}\n            <b>{shop.trackApiKey ? \"set\" : \"not set\"}</b>, sending{\" \"}\n            <b>{shop.waEnabled ? \"on\" : \"off\"}</b>.\n          </p>\n        </Form>\n      </div>\n\n      <div style={S.card}>\n        <h2 style={S.h2}>Test message</h2>\n        <p style={{ ...S.help, marginBottom: 14 }}>\n          Send one to your own number to check the whole path works. It only\n          goes to numbers added to the recipient list in Meta.\n        </p>\n        <fetcher.Form method=\"post\">\n          <input type=\"hidden\" name=\"intent\" value=\"test\" />\n          <div style={S.field}>\n            <label style={S.label} htmlFor=\"testTemplate\">Template</label>\n            <input style={S.input} id=\"testTemplate\" name=\"testTemplate\"\n              defaultValue=\"hello_world\" autoComplete=\"off\" />\n            <p style={S.help}>\n              Only an APPROVED template can be sent. <code style={S.code}>hello_world</code>{\" \"}\n              is Meta's own sample and is approved from the start, so it proves the\n              whole path works while your own templates are still pending.\n            </p>\n          </div>\n          <div style={S.field}>\n            <label style={S.label} htmlFor=\"testTo\">Number</label>\n            <input style={S.input} id=\"testTo\" name=\"testTo\" value={testTo}\n              onChange={(e) => setTestTo(e.target.value)}\n              placeholder=\"9876543210\" autoComplete=\"off\" />\n            <p style={S.help}>+91 is added automatically</p>\n          </div>\n          <button type=\"submit\" style={S.btn} disabled={fetcher.state !== \"idle\"}>\n            {fetcher.state !== \"idle\" ? \"Sending...\" : \"Send\"}\n          </button>\n        </fetcher.Form>\n      </div>\n\n      {templateList.length > 0 && (\n        <div style={S.card}>\n          <h2 style={S.h2}>WhatsApp templates in your account</h2>\n          <p style={{ ...S.help, marginBottom: 14 }}>\n            A template is stored under its name <i>and</i> its language. The app\n            reads the language from this list before sending, so a template filed\n            as en_US works without any change here.\n          </p>\n          <div style={{ overflowX: \"auto\" }}>\n            <table style={{ width: \"100%\", borderCollapse: \"collapse\" }}>\n              <thead>\n                <tr>\n                  <th style={S.th}>Name</th>\n                  <th style={S.th}>Language</th>\n                  <th style={S.th}>Variables</th>\n                  <th style={S.th}>Status</th>\n                </tr>\n              </thead>\n              <tbody>\n                {templateList.map((t: any) => (\n                  <tr key={`${t.name}-${t.language}`}>\n                    <td style={S.td}><code style={S.code}>{t.name}</code></td>\n                    <td style={S.td}>{t.language}</td>\n                    <td style={S.td}>\n                      {t.sends === null ? (\n                        <span style={{ color: \"#616161\" }}>not used</span>\n                      ) : t.sends === t.needs ? (\n                        <span style={{ color: \"#0b5c2e\" }}>{t.needs} — matches</span>\n                      ) : t.sends > t.needs ? (\n                        <span style={{ color: \"#7a5a00\" }}>\n                          needs {t.needs}, app holds {t.sends} — extra ones are dropped\n                        </span>\n                      ) : (\n                        <span style={{ color: \"#8e1c22\" }}>\n                          needs {t.needs}, app holds only {t.sends} — will not send\n                        </span>\n                      )}\n                    </td>\n                    <td style={S.td}>\n                      <span style={{ color: t.status === \"APPROVED\" ? \"#0b5c2e\" : \"#7a5a00\" }}>\n                        {t.status}\n                      </span>\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        </div>\n      )}\n\n      <div style={S.card}>\n        <h2 style={S.h2}>Courier tracking</h2>\n        <p style={{ ...S.help, marginBottom: 14 }}>\n          Out for delivery, Delivered, failed delivery and RTO — Shopify never\n          sends these four. They come from 17TRACK. Two things must be set up:\n        </p>\n        <ol style={{ margin: \"0 0 16px\", paddingLeft: 20, fontSize: 13, lineHeight: 1.8 }}>\n          <li>\n            17TRACK dashboard → Webhook URL:{\" \"}\n            <code style={S.code}>{appUrl}/api/track-webhook</code>\n          </li>\n          <li>\n            A cron every 15 minutes:{\" \"}\n            <code style={S.code}>{appUrl}/api/cron?key=&lt;CRON_SECRET&gt;</code>\n            {!cronSet && (\n              <span style={{ color: \"#8e1c22\" }}> — CRON_SECRET is not in .env yet</span>\n            )}\n          </li>\n        </ol>\n\n        {parcels.length === 0 ? (\n          <p style={S.help}>No parcel has shipped yet.</p>\n        ) : (\n          <div style={{ overflowX: \"auto\" }}>\n            <table style={{ width: \"100%\", borderCollapse: \"collapse\" }}>\n              <thead>\n                <tr>\n                  <th style={S.th}>Order</th>\n                  <th style={S.th}>Courier</th>\n                  <th style={S.th}>Tracking</th>\n                  <th style={S.th}>Status</th>\n                </tr>\n              </thead>\n              <tbody>\n                {parcels.map((p: any) => (\n                  <tr key={p.id}>\n                    <td style={S.td}>{p.order?.orderNumber ?? \"-\"}</td>\n                    <td style={S.td}>{p.carrier ?? \"-\"}</td>\n                    <td style={S.td}>\n                      {p.trackingNo ?? \"-\"}\n                      {p.trackingNo && !p.registered && (\n                        <div style={{ fontSize: 11, color: \"#b98900\" }}>registration pending</div>\n                      )}\n                    </td>\n                    <td style={S.td}>\n                      {p.status}\n                      {p.lastEventDesc && (\n                        <div style={{ fontSize: 11, color: \"#616161\", marginTop: 3 }}>\n                          {p.lastEventDesc}\n                        </div>\n                      )}\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        )}\n      </div>\n\n      {awaitingCancel.length > 0 && (\n        <div style={{ ...S.card, borderColor: \"#e0b4b4\" }}>\n          <h2 style={{ ...S.h2, color: \"#8e1c22\" }}>Waiting to be cancelled</h2>\n          <p style={{ ...S.help, marginBottom: 14 }}>\n            These customers pressed Cancel. Nothing has been cancelled yet — if\n            they press Confirm before the wait is over, the order simply stands.\n          </p>\n          <div style={{ overflowX: \"auto\" }}>\n            <table style={{ width: \"100%\", borderCollapse: \"collapse\" }}>\n              <thead>\n                <tr>\n                  <th style={S.th}>Order</th>\n                  <th style={S.th}>Asked at</th>\n                  <th style={S.th}>Payment</th>\n                </tr>\n              </thead>\n              <tbody>\n                {awaitingCancel.map((o: any) => (\n                  <tr key={o.id}>\n                    <td style={S.td}>\n                      <a href={`https://${domain}/admin/orders/${o.shopifyId}`}\n                        target=\"_blank\" rel=\"noreferrer\">{o.orderNumber}</a>\n                    </td>\n                    <td style={S.td}>\n                      {new Date(o.cancelRequestedAt).toLocaleString(\"en-IN\", {\n                        day: \"numeric\", month: \"short\", hour: \"2-digit\", minute: \"2-digit\",\n                      })}\n                    </td>\n                    <td style={S.td}>\n                      {o.isCod ? \"COD\" : \"Prepaid — tagged only, not cancelled\"}\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        </div>\n      )}\n\n      <div style={S.card}>\n        <h2 style={S.h2}>Customer replies</h2>\n        <p style={{ ...S.help, marginBottom: 14 }}>\n          Everything customers send back. Replies only arrive once the Callback\n          URL is set in Meta:{\" \"}\n          <code style={S.code}>{appUrl}/webhooks/whatsapp</code>, with the\n          <code style={S.code}>messages</code> field subscribed.\n        </p>\n        {replies.length === 0 ? (\n          <p style={S.help}>No reply has come in yet.</p>\n        ) : (\n          <div style={{ overflowX: \"auto\" }}>\n            <table style={{ width: \"100%\", borderCollapse: \"collapse\" }}>\n              <thead>\n                <tr>\n                  <th style={S.th}>When</th>\n                  <th style={S.th}>From</th>\n                  <th style={S.th}>Message</th>\n                  <th style={S.th}>Order</th>\n                  <th style={S.th}>Read as</th>\n                </tr>\n              </thead>\n              <tbody>\n                {replies.map((r: any) => (\n                  <tr key={r.id}>\n                    <td style={S.td}>\n                      {new Date(r.createdAt).toLocaleString(\"en-IN\", {\n                        day: \"numeric\", month: \"short\", hour: \"2-digit\", minute: \"2-digit\",\n                      })}\n                    </td>\n                    <td style={S.td}>{r.from}</td>\n                    <td style={S.td}>{r.text}</td>\n                    <td style={S.td}>{r.order?.orderNumber ?? \"-\"}</td>\n                    <td style={S.td}>\n                      <span style={{\n                        color: r.intent === \"confirm\" ? \"#0b5c2e\"\n                          : r.intent === \"cancel\" ? \"#8e1c22\"\n                          : r.intent === \"stop\" ? \"#7a5a00\"\n                          : \"#616161\",\n                      }}>\n                        {r.intent}\n                      </span>\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        )}\n      </div>\n\n      <div style={S.card}>\n        <h2 style={S.h2}>Recent messages</h2>\n        {messages.length === 0 ? (\n          <p style={S.help}>\n            Nothing yet.{\" \"}\n            <a href={`https://${domain}/admin/orders`} target=\"_blank\" rel=\"noreferrer\">\n              Create an order\n            </a>{\" \"}\n            and come back here.\n          </p>\n        ) : (\n          <div style={{ overflowX: \"auto\" }}>\n            <table style={{ width: \"100%\", borderCollapse: \"collapse\" }}>\n              <thead>\n                <tr>\n                  <th style={S.th}>When</th>\n                  <th style={S.th}>Event</th>\n                  <th style={S.th}>To</th>\n                  <th style={S.th}>Status</th>\n                </tr>\n              </thead>\n              <tbody>\n                {messages.map((m: any) => (\n                  <tr key={m.id}>\n                    <td style={S.td}>\n                      {new Date(m.createdAt).toLocaleString(\"en-IN\", {\n                        day: \"numeric\", month: \"short\", hour: \"2-digit\", minute: \"2-digit\",\n                      })}\n                    </td>\n                    <td style={S.td}>{m.event}</td>\n                    <td style={S.td}>{m.to}</td>\n                    <td style={S.td}>\n                      <Pill status={m.status} />\n                      {m.status === \"failed\" && m.error && (\n                        <div style={{ color: \"#8e1c22\", fontSize: 12, marginTop: 4 }}>\n                          {m.error}\n                        </div>\n                      )}\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n"}, {"path": "prisma/schema.prisma", "fromShas": ["02400fa8bc3e3d014ae846bef0562151b5ea20c8771fe6d51141bc7ef8a0ec58", "b3f02f55910e9ed5f726bcec71df8f2d20122c6dd041b38dd3f301c3482b03ac"], "toSha": "fa37d57cd8b7ab9ddbdf5710834ee78c42984cffc239461cc89113d904077407", "content": "// This is your Prisma schema file,\r\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\r\n\r\ngenerator client {\r\n  provider = \"prisma-client-js\"\r\n}\r\n\r\n// Note that some adapters may set a maximum length for the String type by default, please ensure your strings are long\r\n// enough when changing adapters.\r\n// See https://www.prisma.io/docs/orm/reference/prisma-schema-reference#string for more information\r\ndatasource db {\n  provider  = \"postgresql\"\n  // The app runs through Neon's pooler: a web server opens and closes\n  // connections all day, and the pooler is what keeps the database from\n  // running out of them.\n  url       = env(\"DATABASE_URL\")\n  // Migrations cannot go through the pooler - they need advisory locks\n  // and DDL that PgBouncer does not pass through. So they take the\n  // direct endpoint instead.\n  directUrl = env(\"DIRECT_URL\")\n}\r\n\r\nmodel Session {\r\n  id            String    @id\r\n  shop          String\r\n  state         String\r\n  isOnline      Boolean   @default(false)\r\n  scope         String?\r\n  expires       DateTime?\r\n  accessToken   String\r\n  userId        BigInt?\r\n  firstName     String?\r\n  lastName      String?\r\n  email         String?\r\n  accountOwner  Boolean   @default(false)\r\n  locale        String?\r\n  collaborator  Boolean?  @default(false)\r\n  emailVerified Boolean?  @default(false)\r\n  refreshToken        String?\r\n  refreshTokenExpires DateTime?\r\n}\n\n// ============================================================================\n//  ZakTracking models\n//\n//  Paste this whole block at the very BOTTOM of prisma/schema.prisma.\n//  Leave the Session model and the datasource/generator above it alone.\n//\n//  Then run:   npx prisma migrate dev --name zaktracking\n// ============================================================================\n\n\n/// One row per merchant store. All settings and API keys live here.\nmodel Shop {\n  id          String   @id @default(cuid())\n  domain      String   @unique\n  installedAt DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // --- WhatsApp (Meta Cloud API) ---\n  waEnabled       Boolean @default(false)\n  waPhoneNumberId String?\n  waWabaId        String?\n  waToken         String?\n\n  // --- SMS (phase 2 - after DLT registration in India) ---\n  smsEnabled  Boolean @default(false)\n  smsApiKey   String?\n  smsSenderId String?\n\n  // --- courier tracking (17TRACK) ---\n  trackApiKey String?\n\n  // --- which messages are turned on ---\n  onOrderCreate    Boolean @default(true)\n  onOrderPaid      Boolean @default(true)\n  onFulfilled      Boolean @default(true)\n  /// Off by default. It fires once per order, on the first in-transit scan,\n  /// which on a short route lands moments after the shipped message.\n  onInTransit      Boolean @default(false)\n  onOutForDelivery Boolean @default(true)\n  onDelivered      Boolean @default(true)\n  onCancelled      Boolean @default(true)\n  onAbandoned      Boolean @default(false)\n  codConfirm       Boolean @default(true)\n\n  orders    OrderRecord[]\n  templates Template[]\n  messages  MessageLog[]\n  carts     AbandonedCart[]\n  inbound   InboundMessage[]\n\n  /// When the customer presses Cancel we do not cancel straight away - a\n  /// cancelled Shopify order can never be brought back. We wait, and if\n  /// they press Confirm in the meantime nothing happens at all.\n  autoCancel     Boolean @default(true)\n  /// Minutes to wait before a cancellation request is acted on.\n  cancelGraceMin Int     @default(30)\n\n  /// Discount code for the second abandoned-cart reminder.\n  /// If it is empty the second reminder is not sent at all - better than a fake code.\n  abandonCode String?\n}\n\n\n/// Our own copy of every order, so we never have to ask Shopify again.\nmodel OrderRecord {\n  id     String @id @default(cuid())\n  shopId String\n  shop   Shop   @relation(fields: [shopId], references: [id], onDelete: Cascade)\n\n  shopifyId   String\n  orderNumber String\n  customerName String?\n  phone        String?\n  email        String?\n  totalPrice   String?\n  currency     String?\n  financial    String?\n  gateway      String?\n\n  /// COD or prepaid. Needed as a guard on orders/paid - a COD order also\n  /// fires paid, but only when the courier deposits the cash.\n  isCod        Boolean   @default(false)\n  /// null = not asked yet, true = confirmed, false = declined\n  codConfirmed Boolean?\n  cancelledAt  DateTime?\n  /// Set when the customer presses Cancel on WhatsApp. Cleared the moment\n  /// they press Confirm instead. The cron acts on it once the grace period\n  /// set on the shop has passed.\n  cancelRequestedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  shipments Shipment[]\n  messages  MessageLog[]\n  inbound   InboundMessage[]\n\n  @@unique([shopId, shopifyId])\n  @@index([shopId, createdAt])\n\n  /// \"Portable Blender + 1 more item\" - when a courier update arrives we do\n  /// not have Shopify's payload, so we keep it here.\n  itemLine String?\n  city    String?\n  address String?\n}\n\n\n/// One order can have several parcels. Each parcel gets its own row.\nmodel Shipment {\n  id      String      @id @default(cuid())\n  orderId String\n  order   OrderRecord @relation(fields: [orderId], references: [id], onDelete: Cascade)\n\n  fulfillmentId String\n  trackingNo    String?\n  carrier       String?\n  /// 17TRACK courier code\n  carrierCode   String?\n  trackUrl      String?\n\n  /// pending | info_received | in_transit | out_for_delivery\n  /// | delivered | exception | returned\n  status      String    @default(\"pending\")\n  lastEventAt DateTime?\n\n  /// whether it has been registered with the tracking API\n  registered Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([orderId, fulfillmentId])\n  @@index([trackingNo])\n\n  /// 17TRACK sub_status - e.g. \"DeliveryFailure_NoBody\"\n  subStatus     String?\n  lastEventDesc String?\n  lastEventLoc  String?\n  /// The whole journey as JSON - the tracking page is built from this\n  scans         String?\n  /// How many registration attempts have been made. We give up after 5.\n  regTries      Int     @default(0)\n}\n\n\n/// Every message we send. unique([orderId, event, channel]) is the one thing\n/// that stops the same customer getting \"your order has shipped\" twice.\nmodel MessageLog {\n  id     String @id @default(cuid())\n  shopId String\n  shop   Shop   @relation(fields: [shopId], references: [id], onDelete: Cascade)\n\n  orderId String?\n  order   OrderRecord? @relation(fields: [orderId], references: [id], onDelete: SetNull)\n\n  /// whatsapp | sms\n  channel String\n  /// order_created | cod_confirm | order_paid | shipped\n  /// | out_for_delivery | delivered | cancelled | abandoned_1 | abandoned_2\n  event String\n  to    String\n  body  String\n\n  /// queued | sent | failed\n  status     String  @default(\"queued\")\n  providerId String?\n  error      String?\n\n  sentAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@unique([orderId, event, channel])\n  @@index([shopId, createdAt])\n  @@index([status])\n}\n\n\n/// Where the merchant edits the text of their own messages.\nmodel Template {\n  id     String @id @default(cuid())\n  shopId String\n  shop   Shop   @relation(fields: [shopId], references: [id], onDelete: Cascade)\n\n  event   String\n  channel String\n  enabled Boolean @default(true)\n  body    String\n\n  updatedAt DateTime @updatedAt\n\n  @@unique([shopId, event, channel])\n}\n\n\n/// Abandoned cart. checkouts/update fires 10-15 times for one shopper, so we\n/// upsert on the token and keep pushing lastSeenAt forward.\n/// The moment an order arrives we fill convertedAt - then no reminder goes out.\nmodel AbandonedCart {\n  id     String @id @default(cuid())\n  shopId String\n  shop   Shop   @relation(fields: [shopId], references: [id], onDelete: Cascade)\n\n  token      String\n  phone      String?\n  name       String?\n  recoverUrl String?\n  total      String?\n  currency   String?\n  itemCount  Int     @default(0)\n\n  lastSeenAt  DateTime  @default(now())\n  reminder1At DateTime?\n  reminder2At DateTime?\n  convertedAt DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@unique([shopId, token])\n  @@index([shopId, lastSeenAt])\n}\n\n\n/// Shopify sends the same webhook two or three times (retries, network\n/// glitches). Each delivery carries a unique id - remembering it is the\n/// cheapest way to make every handler idempotent.\nmodel WebhookEvent {\n  id         String   @id\n  topic      String\n  shop       String\n  receivedAt DateTime @default(now())\n\n  @@index([shop, topic])\n}\n\n// ============================================================================\n//  Phase 2 - two changes\n//\n//  1. A WABA ID field on Shop (to read the template list)\n//  2. An OptOut table (to honour STOP)\n//\n//  The script adds both - nothing to do by hand.\n// ============================================================================\n\n/// Anyone who replies STOP lands here. Checked before every send.\n/// The promise in the footer is only true if we honour it.\nmodel OptOut {\n  id     String @id @default(cuid())\n  shopId String\n  phone  String\n\n  createdAt DateTime @default(now())\n\n  @@unique([shopId, phone])\n  @@index([shopId])\n}\n\n\n/// Every reply a customer sends. This is the merchant's inbox: a number on\n/// the WhatsApp Cloud API cannot be opened in the ordinary WhatsApp\n/// Business app, so what is stored here is the only record there is.\n///\n/// waMessageId is unique because Meta retries a webhook it thinks failed.\n/// Without it one \"Cancel\" could be acted on three times.\nmodel InboundMessage {\n  id     String @id @default(cuid())\n  shopId String\n  shop   Shop   @relation(fields: [shopId], references: [id], onDelete: Cascade)\n\n  orderId String?\n  order   OrderRecord? @relation(fields: [orderId], references: [id], onDelete: SetNull)\n\n  /// Meta's own message id\n  waMessageId String @unique\n  from        String\n  text        String\n  /// text | button | interactive | image | ...\n  kind        String\n  /// confirm | cancel | stop | start | none\n  intent      String @default(\"none\")\n\n  createdAt DateTime @default(now())\n\n  @@index([shopId, createdAt])\n}\n"}], "created": [{"path": "app/lib/orders.server.ts", "toSha": "c2bc1be8e4a841f72dd070e03dc7ea95166e1b3185c29c86bfb60a12b886e7f0", "allowOverwriteSha": [], "content": "/**\n * The small part of the Shopify Admin API we actually need after an order\n * already exists: put a tag on it, take a tag off, ask whether it has\n * shipped, and - only when the merchant has allowed it - cancel it.\n *\n * These run from a webhook or from the cron, where there is no logged-in\n * merchant in front of us. `unauthenticated.admin` uses the offline token\n * stored at install time, which is exactly what that is for.\n */\n\nimport { unauthenticated } from \"../shopify.server\";\n\n/** \"9876543210\" -> \"gid://shopify/Order/9876543210\" */\nfunction orderGid(id: string): string {\n  return id.startsWith(\"gid://\") ? id : `gid://shopify/Order/${id}`;\n}\n\nasync function call(domain: string, query: string, variables: any) {\n  const { admin } = await unauthenticated.admin(domain);\n  const res = await admin.graphql(query, { variables });\n  return (await res.json()) as any;\n}\n\n/* ------------------------------------------------------------------ */\n/*  Tags                                                               */\n/* ------------------------------------------------------------------ */\n\n/**\n * Tags are how the merchant sees this in Shopify itself, without opening\n * our app. An order tagged `cod-cancel-requested` can be filtered for in\n * the orders list like any other tag.\n */\nexport async function tagOrder(\n  domain: string,\n  shopifyOrderId: string,\n  add: string[] = [],\n  remove: string[] = [],\n) {\n  const id = orderGid(shopifyOrderId);\n\n  try {\n    if (remove.length) {\n      await call(\n        domain,\n        `#graphql\n         mutation zakTagsRemove($id: ID!, $tags: [String!]!) {\n           tagsRemove(id: $id, tags: $tags) { userErrors { message } }\n         }`,\n        { id, tags: remove },\n      );\n    }\n    if (add.length) {\n      await call(\n        domain,\n        `#graphql\n         mutation zakTagsAdd($id: ID!, $tags: [String!]!) {\n           tagsAdd(id: $id, tags: $tags) { userErrors { message } }\n         }`,\n        { id, tags: add },\n      );\n    }\n    return { ok: true as const };\n  } catch (e: any) {\n    console.log(`[orders] could not tag ${shopifyOrderId}: ${e?.message ?? e}`);\n    return { ok: false as const, error: String(e?.message ?? e) };\n  }\n}\n\n/* ------------------------------------------------------------------ */\n/*  Current state                                                      */\n/* ------------------------------------------------------------------ */\n\nexport type OrderState = {\n  cancelledAt: string | null;\n  fulfillment: string;   // UNFULFILLED | PARTIALLY_FULFILLED | FULFILLED | ...\n  financial: string;     // PENDING | PAID | ...\n};\n\n/**\n * Read before cancelling, never assume. Our own copy of the order can be\n * minutes old, and in those minutes the parcel may have been handed to the\n * courier.\n */\nexport async function orderState(\n  domain: string,\n  shopifyOrderId: string,\n): Promise<OrderState | null> {\n  try {\n    const json = await call(\n      domain,\n      `#graphql\n       query zakOrderState($id: ID!) {\n         order(id: $id) {\n           cancelledAt\n           displayFulfillmentStatus\n           displayFinancialStatus\n         }\n       }`,\n      { id: orderGid(shopifyOrderId) },\n    );\n\n    const o = json?.data?.order;\n    if (!o) return null;\n\n    return {\n      cancelledAt: o.cancelledAt ?? null,\n      fulfillment: String(o.displayFulfillmentStatus ?? \"\"),\n      financial: String(o.displayFinancialStatus ?? \"\"),\n    };\n  } catch (e: any) {\n    console.log(`[orders] could not read ${shopifyOrderId}: ${e?.message ?? e}`);\n    return null;\n  }\n}\n\n/* ------------------------------------------------------------------ */\n/*  Cancel                                                             */\n/* ------------------------------------------------------------------ */\n\n/**\n * Cancelling an order in Shopify cannot be undone. There is no\n * \"uncancel\" - a mistake means creating a fresh order with a new number.\n *\n * That is the whole reason the customer's Cancel button does not cancel\n * anything straight away. It only records a request; this runs later, once\n * the grace period has passed and the customer has not changed their mind.\n *\n * restock is true so the stock comes back. refund is false because this\n * path is only ever used for Cash on Delivery, where no money has moved.\n */\nexport async function cancelOrder(\n  domain: string,\n  shopifyOrderId: string,\n  staffNote: string,\n) {\n  try {\n    const json = await call(\n      domain,\n      `#graphql\n       mutation zakOrderCancel(\n         $orderId: ID!\n         $reason: OrderCancelReason!\n         $refund: Boolean!\n         $restock: Boolean!\n         $notifyCustomer: Boolean\n         $staffNote: String\n       ) {\n         orderCancel(\n           orderId: $orderId\n           reason: $reason\n           refund: $refund\n           restock: $restock\n           notifyCustomer: $notifyCustomer\n           staffNote: $staffNote\n         ) {\n           orderCancelUserErrors { field message }\n           userErrors { field message }\n         }\n       }`,\n      {\n        orderId: orderGid(shopifyOrderId),\n        reason: \"CUSTOMER\",\n        refund: false,\n        restock: true,\n        // Our own cancellation message goes out from the orders/cancelled\n        // webhook. Letting Shopify email as well would say the same thing twice.\n        notifyCustomer: false,\n        staffNote,\n      },\n    );\n\n    const errs = [\n      ...(json?.data?.orderCancel?.orderCancelUserErrors ?? []),\n      ...(json?.data?.orderCancel?.userErrors ?? []),\n    ];\n\n    if (errs.length) {\n      const msg = errs.map((e: any) => e.message).join(\"; \");\n      console.log(`[orders] cancel refused for ${shopifyOrderId}: ${msg}`);\n      return { ok: false as const, error: msg };\n    }\n\n    console.log(`[orders] cancelled ${shopifyOrderId}`);\n    return { ok: true as const };\n  } catch (e: any) {\n    console.log(`[orders] cancel failed for ${shopifyOrderId}: ${e?.message ?? e}`);\n    return { ok: false as const, error: String(e?.message ?? e) };\n  }\n}\n"}, {"path": "app/lib/inbound.server.ts", "toSha": "c89c274ce18f71614e0eb4210e9534bc2160b470f33363dc8e3e922ae2cc3062", "allowOverwriteSha": [], "content": "/**\n * What happens when the customer writes back.\n *\n * Until the Callback URL was filled in, every reply simply vanished - a\n * number on the WhatsApp Cloud API cannot be opened in the ordinary\n * WhatsApp Business app, so the webhook is the only way a reply is ever\n * seen. This file is the other end of that webhook.\n *\n * Three things arrive here and matter: STOP, \"Confirm order\", and\n * \"Cancel order\".\n */\n\nimport db from \"../db.server\";\nimport { queueMessage } from \"./notify.server\";\nimport { blankVars, etaRange } from \"./templates.server\";\nimport { optOut } from \"./notify.server\";\nimport { tagOrder, orderState, cancelOrder } from \"./orders.server\";\n\nexport const TAG_CONFIRMED = \"cod-confirmed\";\nexport const TAG_CANCEL_REQUESTED = \"cod-cancel-requested\";\nexport const TAG_CANCEL_TOO_LATE = \"cod-cancel-after-dispatch\";\n\nexport type Intent = \"confirm\" | \"cancel\" | \"stop\" | \"start\" | \"none\";\n\n/**\n * The exact button labels from our templates. A button reply arrives as the\n * label itself, so matching these is exact and safe - unlike free text,\n * where \"cancel\" could be part of a sentence that means the opposite.\n */\nconst BUTTON_CONFIRM = [\"confirm order\", \"try again tomorrow\", \"send it again\"];\nconst BUTTON_CANCEL = [\"cancel order\", \"cancel it\"];\n\n/** Short free-text replies people actually send. Whole message only. */\nconst TEXT_CONFIRM = [\"confirm\", \"confirmed\", \"yes\", \"y\", \"ok\", \"okay\", \"haan\", \"han\", \"ha\"];\nconst TEXT_CANCEL = [\"cancel\", \"no\", \"nahi\", \"na\"];\nconst TEXT_STOP = [\"stop\", \"unsubscribe\", \"band\"];\nconst TEXT_START = [\"start\", \"resume\", \"subscribe\"];\n\n/** Works out what the customer meant, or \"none\" if it is an ordinary message. */\nexport function readIntent(text: string, isButton: boolean): Intent {\n  const t = String(text || \"\").trim().toLowerCase().replace(/[.!]+$/, \"\");\n  if (!t) return \"none\";\n\n  if (isButton) {\n    if (BUTTON_CONFIRM.includes(t)) return \"confirm\";\n    if (BUTTON_CANCEL.includes(t)) return \"cancel\";\n  }\n\n  if (TEXT_STOP.includes(t)) return \"stop\";\n  if (TEXT_START.includes(t)) return \"start\";\n  if (TEXT_CONFIRM.includes(t)) return \"confirm\";\n  if (TEXT_CANCEL.includes(t)) return \"cancel\";\n\n  return \"none\";\n}\n\n/**\n * The order a reply belongs to.\n *\n * WhatsApp does not tell us which message is being answered, so we take the\n * customer's most recent order. Anything older than thirty days is ignored -\n * a reply that long after the fact is not about that order.\n */\nasync function recentOrderFor(shopId: string, phone: string) {\n  const THIRTY_DAYS = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);\n  return db.orderRecord.findFirst({\n    where: {\n      shopId,\n      phone,\n      cancelledAt: null,\n      createdAt: { gte: THIRTY_DAYS },\n    },\n    orderBy: { createdAt: \"desc\" },\n  });\n}\n\n/**\n * Handles one inbound message. Every reply is stored, whether we understood\n * it or not - that store is the merchant's inbox on the admin page.\n */\nexport async function handleInbound(opts: {\n  shopId: string;\n  domain: string;\n  waMessageId: string;\n  from: string;\n  text: string;\n  kind: string;\n}) {\n  const isButton = opts.kind === \"button\" || opts.kind === \"interactive\";\n  const intent = readIntent(opts.text, isButton);\n\n  const order = await recentOrderFor(opts.shopId, opts.from);\n\n  // The unique constraint on waMessageId is what stops a Meta retry from\n  // confirming, then cancelling, then confirming the same order again.\n  try {\n    await db.inboundMessage.create({\n      data: {\n        shopId: opts.shopId,\n        waMessageId: opts.waMessageId,\n        from: opts.from,\n        text: opts.text.slice(0, 900),\n        kind: opts.kind,\n        intent,\n        orderId: order?.id ?? null,\n      },\n    });\n  } catch {\n    console.log(`[inbound] ${opts.waMessageId} already handled, skipping`);\n    return { intent: \"none\" as Intent, duplicate: true };\n  }\n\n  console.log(\n    `[inbound] ${opts.from} -> \"${opts.text}\" (${intent})` +\n      (order ? ` on ${order.orderNumber}` : \" - no recent order\"),\n  );\n\n  if (intent === \"stop\") {\n    await optOut(opts.shopId, opts.from);\n    return { intent, duplicate: false };\n  }\n\n  if (intent === \"start\") {\n    await db.optOut\n      .delete({ where: { shopId_phone: { shopId: opts.shopId, phone: opts.from } } })\n      .catch(() => {});\n    console.log(`[inbound] ${opts.from} asked to start again`);\n    return { intent, duplicate: false };\n  }\n\n  if (!order) return { intent, duplicate: false };\n\n  if (intent === \"confirm\") {\n    await db.orderRecord.update({\n      where: { id: order.id },\n      // Clearing cancelRequestedAt is the whole point of the grace period:\n      // a Cancel pressed by mistake is undone by pressing Confirm, and\n      // nothing was ever cancelled in Shopify.\n      data: { codConfirmed: true, cancelRequestedAt: null },\n    });\n\n    await tagOrder(opts.domain, order.shopifyId, [TAG_CONFIRMED], [TAG_CANCEL_REQUESTED]);\n\n    const shop = await db.shop.findUnique({ where: { id: opts.shopId } });\n    if (shop?.codConfirm) {\n      const v = blankVars();\n      v.name = order.customerName || \"there\";\n      v.order = order.orderNumber;\n      v.item = order.itemLine || \"your order\";\n      v.eta = etaRange();\n\n      await queueMessage({\n        shopId: opts.shopId,\n        orderId: order.id,\n        event: \"cod_confirmed\",\n        to: opts.from,\n        vars: v,\n      });\n    }\n    return { intent, duplicate: false };\n  }\n\n  if (intent === \"cancel\") {\n    await db.orderRecord.update({\n      where: { id: order.id },\n      data: { codConfirmed: false, cancelRequestedAt: new Date() },\n    });\n    await tagOrder(opts.domain, order.shopifyId, [TAG_CANCEL_REQUESTED], [TAG_CONFIRMED]);\n    console.log(\n      `[inbound] ${order.orderNumber} cancellation requested - waiting out the grace period`,\n    );\n    return { intent, duplicate: false };\n  }\n\n  return { intent, duplicate: false };\n}\n\n/* ------------------------------------------------------------------ */\n/*  The grace period                                                   */\n/* ------------------------------------------------------------------ */\n\n/**\n * Run from the cron. Cancels the orders whose grace period has run out and\n * where the customer never came back to confirm.\n *\n * Three orders are never cancelled here:\n *   - prepaid ones, because money has already moved and a refund is a\n *     decision, not a side effect\n *   - anything already handed to the courier\n *   - anything the merchant has switched auto-cancel off for\n */\nexport async function sweepCancelRequests() {\n  const out = { cancelled: 0, tooLate: 0, skipped: 0 };\n\n  const shops = await db.shop.findMany({ where: { autoCancel: true } });\n\n  for (const shop of shops) {\n    const cutoff = new Date(Date.now() - Math.max(1, shop.cancelGraceMin) * 60 * 1000);\n\n    const due = await db.orderRecord.findMany({\n      where: {\n        shopId: shop.id,\n        cancelledAt: null,\n        cancelRequestedAt: { not: null, lte: cutoff },\n      },\n      take: 25,\n    });\n\n    for (const order of due) {\n      if (!order.isCod) {\n        console.log(\n          `[cancel-sweep] ${order.orderNumber} is prepaid - tagged only, not cancelled`,\n        );\n        await db.orderRecord.update({\n          where: { id: order.id },\n          data: { cancelRequestedAt: null },\n        });\n        out.skipped++;\n        continue;\n      }\n\n      const state = await orderState(shop.domain, order.shopifyId);\n\n      if (!state) {\n        out.skipped++;\n        continue;\n      }\n\n      if (state.cancelledAt) {\n        await db.orderRecord.update({\n          where: { id: order.id },\n          data: { cancelledAt: new Date(state.cancelledAt), cancelRequestedAt: null },\n        });\n        out.skipped++;\n        continue;\n      }\n\n      if (state.fulfillment !== \"UNFULFILLED\") {\n        console.log(\n          `[cancel-sweep] ${order.orderNumber} has already been dispatched - not cancelling`,\n        );\n        await tagOrder(shop.domain, order.shopifyId, [TAG_CANCEL_TOO_LATE], []);\n        await db.orderRecord.update({\n          where: { id: order.id },\n          data: { cancelRequestedAt: null },\n        });\n        out.tooLate++;\n        continue;\n      }\n\n      const res = await cancelOrder(\n        shop.domain,\n        order.shopifyId,\n        \"Cancelled by the customer on WhatsApp\",\n      );\n\n      if (res.ok) {\n        // orders/cancelled fires next and sends the cancellation message,\n        // so nothing is queued from here.\n        await db.orderRecord.update({\n          where: { id: order.id },\n          data: { cancelledAt: new Date(), cancelRequestedAt: null },\n        });\n        out.cancelled++;\n      } else {\n        out.skipped++;\n      }\n    }\n  }\n\n  return out;\n}\n"}, {"path": "app/routes/webhooks.whatsapp.tsx", "toSha": "c493e1b0f0a83d429b8c3b73082c353281a3cc4a60cce2d03a1107feb8aa0625", "allowOverwriteSha": ["e0462cef41d3f7a8ffba03b9ddbf7ed0642a1e1eb4a6fc7a6ce56e90cfa1f93e"], "content": "/**\n * Where WhatsApp replies arrive.\n *\n * A number on the Cloud API cannot be opened in the ordinary WhatsApp\n * Business app, so this endpoint is the only way a customer's reply is ever\n * seen. Without it the Confirm and Cancel buttons are decoration.\n *\n * Meta calls this twice over its life:\n *   GET  - once, to verify the Callback URL (echo hub.challenge back)\n *   POST - for every inbound message and every delivery status, forever\n */\n\nimport type { ActionFunctionArgs, LoaderFunctionArgs } from \"react-router\";\nimport db from \"../db.server\";\nimport { handleInbound } from \"../lib/inbound.server\";\n\nexport async function loader({ request }: LoaderFunctionArgs) {\n  const url = new URL(request.url);\n  const mode = url.searchParams.get(\"hub.mode\");\n  const token = url.searchParams.get(\"hub.verify_token\");\n  const challenge = url.searchParams.get(\"hub.challenge\");\n  const expected = process.env.WA_VERIFY_TOKEN || \"\";\n\n  if (!expected) {\n    console.log(\"[wa-webhook] WA_VERIFY_TOKEN is not set in the environment\");\n    return new Response(\"not configured\", { status: 500 });\n  }\n\n  if (mode === \"subscribe\" && token === expected && challenge) {\n    console.log(\"[wa-webhook] verification succeeded\");\n    return new Response(challenge, {\n      status: 200,\n      headers: { \"Content-Type\": \"text/plain\" },\n    });\n  }\n\n  console.log(\"[wa-webhook] verification failed - token matched:\", token === expected);\n  return new Response(\"forbidden\", { status: 403 });\n}\n\n/** The readable text of a message, whatever type it came in as. */\nfunction textOf(message: any): { text: string; kind: string } {\n  const type = String(message?.type ?? \"\");\n\n  if (type === \"text\") {\n    return { text: String(message.text?.body ?? \"\"), kind: \"text\" };\n  }\n  if (type === \"button\") {\n    return {\n      text: String(message.button?.text ?? message.button?.payload ?? \"\"),\n      kind: \"button\",\n    };\n  }\n  if (type === \"interactive\") {\n    const i = message.interactive ?? {};\n    return {\n      text: String(\n        i.button_reply?.title ?? i.button_reply?.id ?? i.list_reply?.title ?? \"\",\n      ),\n      kind: \"interactive\",\n    };\n  }\n  return { text: `[${type}]`, kind: type || \"other\" };\n}\n\nexport async function action({ request }: ActionFunctionArgs) {\n  const raw = await request.text();\n\n  // Meta disables a webhook that is slow or throws, so this never rethrows\n  // and always answers 200.\n  try {\n    const body = JSON.parse(raw);\n\n    for (const entry of body.entry ?? []) {\n      for (const change of entry.changes ?? []) {\n        const value = change.value ?? {};\n\n        // One installation can have several numbers. The payload says which\n        // one it was, and that is what tells us whose shop this is.\n        const phoneNumberId = String(value?.metadata?.phone_number_id ?? \"\");\n        const shop = phoneNumberId\n          ? await db.shop.findFirst({ where: { waPhoneNumberId: phoneNumberId } })\n          : null;\n\n        for (const message of value.messages ?? []) {\n          const { text, kind } = textOf(message);\n          const from = String(message.from ?? \"\");\n\n          if (!shop) {\n            console.log(\n              `[wa-inbound] ${from} -> \"${text}\" but no shop uses phone number id ${phoneNumberId}`,\n            );\n            continue;\n          }\n\n          await handleInbound({\n            shopId: shop.id,\n            domain: shop.domain,\n            waMessageId: String(message.id ?? `${from}-${message.timestamp ?? Date.now()}`),\n            from,\n            text,\n            kind,\n          });\n        }\n\n        // Delivery receipts. Useful when a message says \"sent\" on our side\n        // but never reached the phone.\n        for (const status of value.statuses ?? []) {\n          const id = String(status?.id ?? \"\");\n          const state = String(status?.status ?? \"\");\n          if (!id || !state) continue;\n\n          if (state === \"failed\") {\n            const reason =\n              status?.errors?.[0]?.title ?? status?.errors?.[0]?.message ?? \"failed\";\n            await db.messageLog\n              .updateMany({\n                where: { providerId: id },\n                data: { status: \"failed\", error: String(reason) },\n              })\n              .catch(() => {});\n            console.log(`[wa-status] ${status.recipient_id} -> failed: ${reason}`);\n          } else if (state === \"read\" || state === \"delivered\") {\n            console.log(`[wa-status] ${status.recipient_id} -> ${state}`);\n          }\n        }\n      }\n    }\n  } catch (error) {\n    console.log(\"[wa-webhook] could not handle payload:\", error);\n  }\n\n  return new Response(\"ok\", { status: 200 });\n}\n"}]};

const root = process.cwd();
const sha = (s) => createHash("sha256").update(s, "utf8").digest("hex");
const read = (p) => readFileSync(join(root, p), "utf8");

if (!existsSync(join(root, "app", "routes")) || !existsSync(join(root, "prisma"))) {
  console.error("ERROR: this is not the project root (app/routes and prisma not found).");
  process.exit(1);
}

const problems = [];
const plan = [];

for (const f of PAYLOAD.modified) {
  if (!existsSync(join(root, f.path))) {
    problems.push(`missing file: ${f.path}`);
    continue;
  }
  const current = sha(read(f.path));
  if (current === f.toSha) {
    console.log(`skip    ${f.path} (already patched)`);
    continue;
  }
  if (!f.fromShas.includes(current)) {
    problems.push(
      `${f.path} is not a version this patch was built against\n` +
      `          expected ${f.fromShas.map((s) => s.slice(0, 16)).join(" or ")}\n` +
      `          found    ${current.slice(0, 16)}`,
    );
    continue;
  }
  plan.push(f);
}

for (const f of PAYLOAD.created) {
  if (existsSync(join(root, f.path))) {
    const current = sha(read(f.path));
    if (current === f.toSha) {
      console.log(`skip    ${f.path} (already in place)`);
      continue;
    }
    if (!f.allowOverwriteSha.includes(current)) {
      problems.push(`${f.path} already exists and is not a file this patch created`);
      continue;
    }
  }
  plan.push(f);
}

if (problems.length) {
  console.error("\nNothing was written. Fix these first:\n");
  for (const p of problems) console.error("  - " + p);
  process.exit(1);
}

if (plan.length === 0) {
  console.log("\nEverything is already applied. Nothing to do.");
  process.exit(0);
}

for (const f of plan) {
  mkdirSync(dirname(join(root, f.path)), { recursive: true });
  writeFileSync(join(root, f.path), f.content, "utf8");
  const after = sha(read(f.path));
  if (after !== f.toSha) {
    console.error(`ERROR: ${f.path} was written but its checksum is wrong. Stopping.`);
    process.exit(1);
  }
  console.log(`ok      ${f.path}`);
}

console.log(`
Done - ${plan.length} file(s) written and checksum-verified.

Next:
  npx prisma migrate dev --name inbound_and_cancel
`);
